// --- Behavioural enums ------------------------------------------------------
enum class Type   : uint8_t { Continuous, Select, Toggle, Int };
enum class Scope  : uint8_t { Patch, Performance, Global };
enum class Widget : uint8_t { Knob, Envelope, Grid };  // UI rendering hint

// Curve maps a normalized control position t (0..1) to engineering units:
//   Lin : min + t*(max-min)
//   Log : min * pow(max/min, t)              (perceptual freq/time sweeps)
//   Seg2: two linear segments meeting at 'mid' when t == 0.5
//         (v1 envelope-slope mapping, Mapping.h cc_to_curve)
enum class Curve  : uint8_t { Lin, Log, Seg2 };

// Which physical control a parameter binds to.
//
// DERIVED from `type` by default:
//     Continuous -> Pot        (a value you sweep)
//     Select     -> Encoder    (a detented list)
//     Toggle     -> Switch     (encoder push)
//
// A parameter may override this via `ui.control` in params.yaml when
// ergonomics beat the type rule — e.g. env_pitch.depth is continuous but
// binds to an encoder so the three envelope pages share a pot layout.
// Overrides are deliberately rare: each one is a place the panel stops
// being predictable from the parameter's type alone.
enum class Control : uint8_t { Pot = 0, Encoder = 1, Switch = 2 };

// ParamDesc::visIf sentinel for "no condition, always visible".
// MUST NOT be 0: ParamID 0x0000 is osc1.wave, a real parameter that other
// rows genuinely depend on.
inline constexpr uint16_t kNoVisDep = 0xFFFF;

