inline constexpr size_t kParamCount = sizeof(kParams) / sizeof(kParams[0]);

// --- Lookups -------------------------------------------------------------------
// Linear scans are constexpr-friendly and fine at control rate (UI, MIDI
// dispatch).  NOTHING in the audio ISR looks parameters up by id — the
// engine caches direct indices at boot (ParameterStore, Phase 1).

inline constexpr const ParamDesc* find(uint16_t id) {
    for (size_t i = 0; i < kParamCount; ++i)
        if (kParams[i].id == id) return &kParams[i];
    return nullptr;
}

inline constexpr const ParamDesc* findByCC(uint8_t cc) {
    for (size_t i = 0; i < kParamCount; ++i)
        if (kParams[i].cc == static_cast<int16_t>(cc)) return &kParams[i];
    return nullptr;
}

// NRPN number == ParamID by construction (brief §5.2).
inline constexpr uint8_t nrpnMsb(uint16_t id) { return static_cast<uint8_t>((id >> 7) & 0x7F); }
inline constexpr uint8_t nrpnLsb(uint16_t id) { return static_cast<uint8_t>(id & 0x7F); }
inline constexpr uint16_t idFromNrpn(uint8_t msb, uint8_t lsb) {
    return static_cast<uint16_t>((static_cast<uint16_t>(msb & 0x7F) << 7) | (lsb & 0x7F));
}

// Compile-time guarantees — a bad regeneration cannot even compile.
static_assert(kParamCount == 160, "param count changed — regenerate consumers");
// Dereferencing in a constant expression: if find() ever returned nullptr
// this line would be a hard compile error — stronger than a null compare,
// and clean under -Waddress (GCC can prove the pointer is never null).
static_assert(find(ID::FILTER_CUTOFF)->id == ID::FILTER_CUTOFF, "table self-check failed");

